Lemma consts_rep_nw : forall L (m m' : mem), consts_rep L m -> agree_on (in_rngs (consts_rngs L)) m m' ->
  agree_on (fun x => l_T L + 2768 <= x < l_T L + 3168) m m' -> consts_rep L m'.
Proof.
